from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(17,'symetrie','La symétrie axiale','4 · Espace et géométrie',
'Axes · Pliage · Quadrillage · Figures à compléter',
['Reconnaître les axes de symétrie d’une figure.','Compléter une figure pour la rendre symétrique.','Construire un symétrique sur quadrillage.'],
['Quadrillages, perpendiculaires et distances.'],[
page(1,'Reconnaître une symétrie',
bloc('definition',r'Une droite est un axe de symétrie d’une figure si, en pliant la feuille le long de cette droite, les deux parties de la figure se superposent exactement. Le calque, retourné le long de l’axe, fait la même vérification.'),
r'@FIG:cours-symetrie@',
bloc('exemple',r'Le carré a 4 axes de symétrie, le rectangle en a 2, le triangle équilatéral 3, le cercle une infinité. Certaines figures n’en ont aucun : un pliage qui déborde suffit à l’affirmer.'),
bloc('attention',r'Les diagonales du rectangle ne sont pas des axes de symétrie : le pliage le long d’une diagonale ne superpose pas les deux moitiés. Toujours imaginer ou réaliser le pliage.')),
page(2,'Construire sur quadrillage',
bloc('savoirfaire',r'Sur quadrillage, avec un axe vertical : le symétrique d’un point se place de l’autre côté, à autant de carreaux de l’axe, sur la même ligne. Avec un axe horizontal, on compte les carreaux au-dessus et au-dessous.','Compter les carreaux'),
bloc('propriete',r'La symétrie conserve les longueurs et les formes : le symétrique d’un segment de 4 carreaux mesure 4 carreaux. Un point situé sur l’axe est son propre symétrique : il ne bouge pas.'),
bloc('savoirfaire',r'Pour compléter une figure dont l’axe est tracé : traiter les sommets un par un, placer chaque symétrique, puis relier dans le même ordre. Contrôler en pliant mentalement.','Compléter une figure'),
bloc('exemple',r'Les lettres offrent de bons exemples : A possède un axe vertical, B un axe horizontal, H les deux, et F n’en a aucun.'))
],[
E('Axe ou pas ?',r'Pour chaque figure dessinée, dire si la droite tracée en pointillés est un axe de symétrie.',r'Le pliage superpose les deux moitiés du cœur et du sapin : $\res{\text{oui}}$ pour les deux. Pour le drapeau, la partie gauche déborde après pliage : $\res{\text{non}}$.','Imaginer le pliage le long de la droite.','assert 1==1',figure='sym-1'),
E('Compter les axes',r'Donner le nombre d’axes de symétrie : du carré, du rectangle et du triangle équilatéral dessinés.',r'Le carré en a $\res4$ : deux médianes et deux diagonales. Le rectangle en a $\res2$ : ses diagonales n’en sont pas. Le triangle équilatéral en a $\res3$.','Tester médianes et diagonales séparément.','assert 4>3>2',figure='sym-2'),
E('La diagonale piégée',r'Milo plie un rectangle le long d’une diagonale et dit : « C’est un axe de symétrie, les deux triangles sont pareils. » Que lui répondre ?',r'Les deux triangles sont bien superposables, mais le pliage ne les superpose pas : des coins dépassent. La diagonale $\res{\text{n’est pas un axe}}$ de symétrie : l’axe exige la superposition par pliage.','Distinguer « même forme » et « superposés par pliage ».','assert 1==1',figure='sym-3'),
E('Le symétrique d’un point',r'Placer le symétrique de chaque point marqué par rapport à l’axe vertical tracé.',r'A est à 2 carreaux à gauche de l’axe : son symétrique est à 2 carreaux à droite, sur la même ligne. De même pour B (3 carreaux) et C (1 carreau). Les réponses figurent en vert.','Compter les carreaux jusqu’à l’axe, puis autant au-delà.','assert 2==2 and 3==3',figure='sym-4'),
E('Compléter la maison',r'Compléter le dessin de la maison pour que l’axe vertical soit un axe de symétrie.',r'Chaque sommet reçoit son symétrique de l’autre côté, à même distance de l’axe ; on relie ensuite dans le même ordre. La moitié ajoutée figure en vert.','Traiter sommet par sommet avant de relier.','assert 1==1',figure='sym-5'),
E('Axe horizontal',r'Construire le symétrique du segment [AB] par rapport à l’axe horizontal tracé.',r'A est à 1 carreau au-dessus de l’axe : son image est à 1 carreau au-dessous. B, à 3 carreaux, descend à 3 carreaux. Le segment image, en vert, mesure autant que [AB].','Compter au-dessus puis au-dessous.','assert 3-1==2',figure='sym-6'),
E('Le papillon',r'Compléter le papillon pour que la droite horizontale soit un axe de symétrie.',r'Les sommets de l’aile dessinée se reflètent sous l’axe, à égale distance. Les points posés sur l’axe ne bougent pas. L’aile ajoutée figure en vert.','Les points de l’axe restent en place.','assert 1==1',figure='sym-7'),
E('Les lettres',r'Parmi les lettres A, B, H et F dessinées, dire lesquelles ont un axe de symétrie vertical, horizontal, ou aucun.',r'A : axe $\res{\text{vertical}}$. B : axe $\res{\text{horizontal}}$. H : $\res{\text{les deux}}$. F : $\res{\text{aucun}}$.','Tester les deux directions de pliage.','assert 2==2',figure='sym-8'),
E('Chercher l’erreur',r'Léa a construit le symétrique du triangle par rapport à l’axe vertical, mais un sommet est mal placé. Lequel ? Corriger.',r"Le sommet $\res{B'}$ est à 2 carreaux de l’axe alors que B est à 3 carreaux : les distances à l’axe doivent être égales. Le point corrigé figure en vert.",'Comparer les distances à l’axe, point par point.','assert 3!=2',figure='sym-9'),
E('Sur l’axe',r'Le segment [AB] a une extrémité A posée sur l’axe. Construire son symétrique. Que devient le point A ?',r'A est sur l’axe : il est $\res{\text{son propre symétrique}}$. Seul B se reflète ; le segment image part donc du même point A. Le tracé figure en vert.','Un point de l’axe ne bouge pas.','assert 0==0',figure='sym-10'),
E('Le carrelage',r'Compléter le motif du carrelage pour que l’axe vertical soit un axe de symétrie, en coloriant les bonnes cases.',r'Chaque case colorée a sa jumelle de l’autre côté, à même distance de l’axe et sur la même ligne : 6 cases sont à colorier. Elles figurent en vert.','Associer les cases deux par deux à travers l’axe.','assert 6==6',figure='sym-11'),
E('Deux axes à la fois',r'Compléter la figure pour qu’elle admette l’axe vertical et l’axe horizontal tracés comme axes de symétrie.',r'On reflète d’abord à travers l’axe vertical, puis tout le résultat à travers l’axe horizontal : la figure finale compte 4 quarts identiques. Les trois quarts ajoutés figurent en vert.','Appliquer les deux pliages l’un après l’autre.','assert 4==4',figure='sym-12'),
E('Les longueurs conservées',r'Le segment [CD] mesure 4 carreaux. Construire son symétrique par rapport à l’axe, puis donner sa longueur sans la mesurer. Justifier.',r'La symétrie conserve les longueurs : le segment image mesure $\res4$ carreaux, comme [CD]. La construction en vert le confirme.','Citer la propriété de conservation.','assert 4==4',figure='sym-13'),
E('Le bateau du port',r'Compléter le dessin du bateau et de sa voile pour que l’axe vertical soit un axe de symétrie du dessin complet.',r'Coque et voile se reflètent sommet par sommet ; le mât, posé sur l’axe, reste en place. Le demi-dessin ajouté figure en vert.','Commencer par les points les plus proches de l’axe.','assert 1==1',figure='sym-14'),
E('Vrai ou faux ?',r'Pour chaque phrase, dire si elle est vraie et corriger si besoin : « Le symétrique d’un point est toujours de l’autre côté de l’axe. » ; « Une figure a au plus un axe de symétrie. »',r'La première est $\res{\text{presque vraie}}$ : elle oublie les points situés sur l’axe, qui ne bougent pas. La seconde est $\res{\text{fausse}}$ : le carré a 4 axes et le cercle en a une infinité.','Chercher les cas particuliers avant de valider.','assert 4>1',figure='sym-15')
],reperes=['Axes et pliages','Symétriques de points et segments','Figures complétées sur quadrillage','Propriétés conservées'],deco='geometrie')

chapitre(18,'solides','Solides, patrons et espace','4 · Espace et géométrie',
'Cubes · Pavés · Patrons · Assemblages · Déplacements',
['Nommer et décrire les solides usuels.','Reconnaître et construire un patron du cube.','Dénombrer des cubes et coder des déplacements.'],
['Figures planes usuelles et quadrillage.'],[
page(1,'Reconnaître les solides',
bloc('definition',r'Les solides usuels sont le cube, le pavé (ou parallélépipède rectangle), la boule, le cylindre, le cône, la pyramide et le prisme droit. Les solides dont toutes les faces sont plates sont des polyèdres ; la boule, le cylindre et le cône ont des surfaces courbes.'),
r'@FIG:cours-solides@',
bloc('propriete',r'Une face est une surface plate du solide ; une arête est un segment où deux faces se rejoignent ; un sommet est un point où des arêtes se rencontrent.'),
bloc('attention',r'En perspective, certaines faces, arêtes et sommets sont cachés : les arêtes invisibles se dessinent en pointillés. Les faces carrées peuvent sembler penchées : la perspective déforme les angles, pas la réalité.')),
page(2,'Décrire les solides',
bloc('propriete',r'Le cube a 6 faces carrées, 12 arêtes et 8 sommets. Le pavé a 6 faces rectangulaires, 12 arêtes et 8 sommets : ses faces opposées sont identiques.'),
bloc('propriete',r'Une pyramide a une base polygonale et des faces latérales triangulaires qui se rejoignent en un sommet. Un prisme droit a deux bases superposables et parallèles, reliées par des faces rectangulaires.'),
bloc('exemple',r'Décrire, c’est donner le nombre et la nature des faces : « 6 faces carrées » suffit à reconnaître le cube ; « deux bases triangulaires et trois faces rectangulaires » décrit un prisme droit à base triangulaire.'),
bloc('savoirfaire',r'Pour identifier un solide en perspective : compter les faces visibles et cachées, observer la forme des faces, chercher les bases. Justifier par les propriétés, pas par l’allure.','Identifier en perspective')),
page(3,'Le patron du cube',
bloc('definition',r'Un patron d’un solide est un dessin d’un seul tenant qui, plié le long des arêtes, reconstruit le solide. Un patron du cube est formé de 6 carrés identiques bien disposés.'),
r'@FIG:cours-patron@',
bloc('savoirfaire',r'Pour tester un patron de cube, plier mentalement : choisir une face de fond, puis relever les autres une à une. Si deux carrés se superposent ou si une face manque, ce n’est pas un patron.','Plier mentalement'),
bloc('exemple',r'La croix de 6 carrés est un patron du cube. Quatre carrés alignés avec deux carrés du même côté n’en forment pas un : deux faces se superposent. Sur un patron du cube, les faces opposées sont séparées par une face.')),
page(4,'Assemblages et déplacements',
bloc('savoirfaire',r'Pour compter les cubes d’un assemblage, compter étage par étage sans oublier les cubes cachés qui portent les étages supérieurs. Un cube en hauteur repose toujours sur un cube ou un empilement.','Compter les cubes cachés'),
bloc('exemple',r'Un déplacement sur quadrillage se code avec un vocabulaire précis : avancer d’un nombre de cases, pivoter d’un quart de tour à droite ou à gauche. La même suite d’instructions, exécutée depuis un autre départ, donne un autre chemin.'),
bloc('savoirfaire',r'Pour exécuter un programme de déplacement : marquer la case et l’orientation de départ, puis suivre les instructions une à une en dessinant le chemin. Pour coder un chemin : le découper en avancées et en quarts de tour.','Coder et exécuter'),
bloc('attention',r'« À droite » dépend de l’orientation de celui qui avance : après un demi-tour, sa droite a changé de côté. Toujours suivre l’orientation du personnage, pas celle du lecteur.'))
],[
E('Nommer les solides',r'Nommer chacun des six solides dessinés.',r'Dans l’ordre : $\res{\text{cube}}$, $\res{\text{pavé}}$, $\res{\text{cylindre}}$, $\res{\text{pyramide}}$, $\res{\text{cône}}$ et $\res{\text{boule}}$.','Observer les faces et les surfaces courbes.','assert 6==6',figure='sol-1'),
E('La carte d’identité du cube',r'Donner le nombre de faces, d’arêtes et de sommets d’un cube, et la nature de ses faces.',r'Le cube a $\res6$ faces $\res{\text{carrées}}$, $\res{12}$ arêtes et $\res8$ sommets.','Compter sur la perspective, faces cachées comprises.','assert 6+8==14 and 12==12',figure='sol-2'),
E('Décrire un pavé',r'Décrire le pavé dessiné : nombre et nature des faces, arêtes et sommets. Que dire des faces opposées ?',r'Le pavé a $\res6$ faces $\res{\text{rectangulaires}}$, 12 arêtes et 8 sommets. Les faces opposées sont $\res{\text{identiques}}$ deux à deux.','S’appuyer sur la comparaison avec le cube.','assert 6==6 and 12==12 and 8==8',figure='sol-3'),
E('Les faces de la pyramide',r'La pyramide dessinée a une base carrée. Donner la nature et le nombre de ses faces.',r'Elle a une base $\res{\text{carrée}}$ et $\res4$ faces latérales $\res{\text{triangulaires}}$, soit 5 faces en tout.','Séparer la base des faces latérales.','assert 4+1==5',figure='sol-4'),
E('Le prisme droit',r'Décrire le prisme droit dessiné : ses bases et ses autres faces.',r'Ses deux bases sont des $\res{\text{triangles}}$ superposables ; les $\res3$ autres faces sont des $\res{\text{rectangles}}$. C’est un prisme droit à base triangulaire.','Chercher d’abord les deux bases jumelles.','assert 2+3==5',figure='sol-5'),
E('Patron ou pas ?',r'Parmi les trois dispositions de six carrés, lesquelles sont des patrons de cube ?',r'La croix et la disposition en T se plient en cube : $\res{\text{patrons}}$. La disposition où deux carrés sont du même côté d’une ligne de quatre fait se superposer deux faces : $\res{\text{pas un patron}}$.','Plier mentalement face par face.','assert 6==6',figure='sol-6'),
E('Les faces opposées',r'Sur le patron en croix, la face du milieu est posée au fond. Quelle face se retrouve opposée à la face marquée A ?',r'En pliant, la face opposée à A est celle qui en est séparée par une face sur le patron : c’est la face marquée $\res C$. Deux faces voisines sur le patron ne peuvent pas être opposées.','Sauter une face sur le patron.','assert 1==1',figure='sol-7'),
E('Compléter le patron',r'Cinq carrés sont dessinés ; il manque une face. Donner une position du sixième carré qui donne un patron de cube, et une position qui n’en donne pas. Justifier.',r'Placé à droite du deuxième carré de la colonne, le sixième carré ferme le cube : cette position $\res{\text{convient}}$ ; elle figure en vert. Collé sous le carré de gauche, il formerait un bloc de quatre carrés : deux faces se superposeraient au pliage, position $\res{\text{interdite}}$.','Tester chaque position par pliage mental.','assert 5+1==6',figure='sol-8'),
E('Les cubes cachés',r'Compter les cubes de l’assemblage dessiné, en n’oubliant pas les cubes cachés.',r'Étage du bas : $3\times2=6$ cubes. Étage du milieu : 3 cubes. Étage du haut : 1 cube. Total : $6+3+1=\res{10}$ cubes ; les cubes porteurs cachés sont comptés.','Compter étage par étage, du bas vers le haut.','assert 6+3+1==10',figure='sol-9'),
E('La bonne vue',r'Associer à l’assemblage la vue de face et la vue de dessus parmi les trois vignettes proposées.',r'La vue de face montre les hauteurs des colonnes : vignette $\res2$. La vue de dessus montre les cases occupées au sol : vignette $\res3$. La vignette 1 ne correspond à aucun point de vue.','Imaginer l’assemblage depuis chaque position.','assert 2!=3',figure='sol-10'),
E('Construire un patron',r'Tracer un patron d’un cube de 3 cm d’arête, en vraie grandeur.',r'On dessine une croix de six carrés de $\res{3\ \mathrm{cm}}$ de côté, à la règle et à l’équerre ; les carrés partagent leurs côtés exactement. Le patron, plié, referme le cube : le tracé figure en vert.','Tous les carrés ont le même côté de 3 cm.','assert 3*12==36',figure='sol-11'),
E('Agrandir l’assemblage',r'L’assemblage dessiné compte 7 cubes. Combien de cubes faut-il ajouter pour obtenir un grand cube de 2 cubes de côté ? Et pour un grand cube de 3 cubes de côté ?',r'Un cube de côté 2 contient $2\times2\times2=8$ cubes : il manque $8-7=\res1$ cube. Un cube de côté 3 en contient $3\times3\times3=27$ : il manquerait $27-7=\res{20}$ cubes.','Calculer le total visé avant de soustraire.','assert 2*2*2==8 and 8-7==1 and 3*3*3==27 and 27-7==20',figure='sol-12'),
E('Coder un chemin',r'Écrire la suite d’instructions qui mène le pion de la case départ à la case but, en suivant le chemin dessiné : avancer, pivoter à droite ou à gauche.',r'Un codage correct est : avancer de 3 cases ; pivoter d’un quart de tour à droite ; avancer de 1 case ; pivoter d’un quart de tour à droite ; avancer de 3 cases. L’arrivée est bien la case but, une case $\res{\text{sous le départ}}$ après le retour.','Suivre l’orientation du pion, pas celle du lecteur.','assert 3-3==0 and 0-1==-1',figure='sol-13'),
E('Exécuter un programme',r'Le pion part de la case marquée, tourné vers la droite de la feuille. Exécuter : avancer de 2 cases ; pivoter d’un quart de tour à gauche ; avancer de 2 cases ; pivoter d’un quart de tour à gauche ; avancer de 1 case. Où arrive-t-il ?',r'Le pion va 2 cases vers la droite, monte de 2 cases, puis revient de 1 case vers la gauche : il arrive 1 case à droite et 2 cases au-dessus du départ, tourné vers la $\res{\text{gauche de la feuille}}$. Le chemin figure en vert.','Mettre à jour l’orientation après chaque quart de tour.','assert (2-1,2)==(1,2)',figure='sol-14'),
E('Le dé à compléter',r'Sur un dé, les points des faces opposées totalisent toujours 7. Compléter le patron du dé : les faces 1, 2 et 3 sont déjà placées. Où écrire 4, 5 et 6 ?',r'La face opposée à 3 porte $7-3=\res4$ ; celle opposée à 2 porte $\res5$ ; celle opposée à 1 porte $\res6$. Sur le patron, chaque paire opposée est séparée par une face ; les valeurs figurent en vert.','Associer les paires qui totalisent 7, puis les placer.','assert 3+4==2+5==1+6==7',figure='sol-15')
],reperes=['Solides usuels et vocabulaire','Faces, arêtes et descriptions','Patrons du cube','Assemblages et déplacements codés'],deco='espace')
